2012 03 27</p></p><br /><br />
<p><strong>p.</strong></p> 15<br />
SYMBOLS<br />
&#43; 1) after a number or range of numbers, it means "or more" (e.g., "6&ndash;10+ mm" means "6 to 10 or more mm"); 2) between words (e.g., plant structures, word elements in etymologies) it means "plus" (e.g., "tube + throat 12&ndash;16 mm" means that the tube and throat taken together are 12&ndash;16 mm)<br />
<span class="erratum-detail"> inserted just below '1', just above '&plusmn;'</span><br />
2012 03 27</p></p><br /><br />
<p><strong>p.</strong></p> 15<br />
SYMBOLS<br />
broken diamond weedy, alien taxon; see Conventions for further explanation<br />
