2012 03 27</p></p><br /><br />
<p><strong>p.</strong></p> 15<br />
SYMBOLS<br />
diamond weedy, alien taxon; see Conventions for further explanation<br />
<span class="erratum-detail"> 'plant' made 'taxon'</span><br />
2012 03 27</p></p><br /><br />
<p><strong>p.</strong></p> 18<br />
GLOSSARY<br />
aquatic. Growing under, in, or on water (generally fresh; if brackish, saline, or marine, so indicated), whether rooted in bottom or floating, and including plants with parts of shoots submersed but with other parts above water (e.g., <em>Potamogeton gramineus</em>); excluding plants of seeps or wet rocks. (see emersed, submersed)<br />
<span class="erratum-detail"> '(e.g., <em>Potamogeton gramineus</em>)' moved</span><br />
2012 03 27</p></p><br /><br />
<p><strong>p.</strong></p> 22<br />
GLOSSARY<br />
ellipsoid. In the shape of a flattened or elongated sphere, widest at the middle and tapered equally to both ends, as a fruit; wider than linear. (see elliptic, linear, oblong)<br />
<span class="erratum-detail"> 'circle' made 'sphere'; 'in three dimensions,' deleted</span><br />
2012 03 27</p></p><br /><br />
<p><strong>p.</strong></p> 22<br />
GLOSSARY<br />
elliptic. In the shape of a flattened or elongated circle, widest at the middle and tapered equally to both ends, as a leaf; wider than linear. (see ellipsoid, linear, oblong)<br />
<span class="erratum-detail"> 'in two dimensions (i.e., in one plane),' deleted</span><br />
2012 03 27</p></p><br /><br />
<p><strong>p.</strong></p> 24<br />
GLOSSARY<br />
infraspecific. Below the species level or within a species; pertaining to variation within a species, whether taxonomically significant (e.g., characterizing subspecies or varieties) or not (e.g., characterizing forms or minor variants).<br />
<span class="erratum-detail"> 'i.e.' made 'e.g.'</span><br />
2012 03 27</p></p><br /><br />
<p><strong>p.</strong></p> 27<br />
GLOSSARY<br />
mericarp. One of the generally dry, generally indehiscent, 1&ndash;few-seeded, 1-carpelled segments into which certain fruits separate at maturity (e.g., those of Apiaceae).<br />
<span class="erratum-detail"> deleted &plusmn; repeated phrase '(generally dry, indehiscent, 1-seeded)'</span><br />
2012 03 27</p></p><br /><br />
<p><strong>p.</strong></p> 28<br />
GLOSSARY<br />
papillate. Pertaining to a surface (e.g., of a leaf, stigma, fruit) bearing small, rounded or conic protuberances (papillae; singular papilla).<br />
<span class="erratum-detail"> deleted comma after 'rounded'</span><br />
2012 03 27</p></p><br /><br />
<p><strong>p.</strong></p> 30<br />
GLOSSARY<br />
pome. In Rosaceae, a fleshy, indehiscent fruit, such as an apple or pear; derived from a hypanthium (represented as outer fleshy material and skin) surrounding and &plusmn; fused to a compound ovary (represented as (1)2&ndash;5 papery-walled, radiating segments alternating with fleshy material, as in, e.g., <em>Amelanchier utahensis</em> fruit) or to (1)2&ndash;5 free ovaries, each with a &plusmn; stony outer layer. (see berry, drupe)<br />
<span class="erratum-detail"> moved 'e.g., <em>Amelanchier utahensis</em> fruit'; added 'as in'</span><br />
2012 03 27</p></p><br /><br />
<p><strong>p.</strong></p> 30<br />
GLOSSARY<br />
prickle. Sharp-pointed, stiff or somewhat flexible projection, originating at or near the surface and neither subtending an axillary bud or branch nor subtended by a leaf or leaf scar, without leaves, leaf scars, buds, or branches (e.g., <em>Rosa woodsii</em> stem); loosely used for any sharp projection. (see armed, spine, thorn)<br />
<span class="erratum-detail"> moved '(e.g., <em>Rosa woodsii</em> stem)'</span><br />
2012 03 27</p></p><br /><br />
<p><strong>p.</strong></p> 34<br />
GLOSSARY<br />
vein. 1. Tissue specialized for transport of substances within a plant: water and dissolved inorganic substances (e.g., mineral nutrients) through the xylem; energy-rich, organic compounds (products of photosynthesis) through the phloem. 2. Strand of such tissue, often seen as a line in surface view and as a bundle in transverse section.<br />
<span class="erratum-detail"> comma made semicolon after 'xylem'</span><br />
2012 03 27</p></p><br /><br />
<p><strong>p.</strong></p> 34<br />
GLOSSARY<br />
valve. 1. In legumes or capsules opening by longitudinal lines, one of the parts into which the fruit is dehiscent (such fruits valvate). 2. In anthers, the flap of tissue resulting from dehiscence by a curved line (e.g., Lauraceae, some Berberidaceae). 3. In Ophioglossaceae, one of the parts into which the sporangium is dehiscent.<br />
<span class="erratum-detail"> period added before '3.'</span><br />
2012 03 27</p></p><br /><br />
<p><strong>p.</strong></p> 53<br />
lines 15&ndash;16<br />
