THINGS TO REMEMBER WHEN USING THIS BOOK<br />
Assumptions. Unless stated otherwise, number of flowers is per inflorescence, of petals is per flower, of seeds is per fruit (so if per chamber, that would be specified), etc. Also, unless stated otherwise, keys and descriptions refer to plant parts in their mature condition; that is, after they have expanded fully from their embryonic states, excluding any expansion subsequent to that, as happens for example when flower parts (e.g., ovary, sepals) expand in association with fruit set.<br />
<span class="erratum-detail"> 'Also, unless stated otherwise, keys and descriptions refer to plant parts in their mature condition; that is, after they have expanded fully from their embryonic states, excluding any expansion subsequent to that, as happens for example when flower parts (e.g., ovary, sepals) expand in association with fruit set.' added</span><br />
2013 11 19</p></p><br /><br />
