<p><strong>p.</strong></p> 848 [location or approximate location where note would appear in TJM2 were it not unabridged and therefore only in eFlora]<br />
MONARDELLA odoratissima<br />
UNABRIDGED NOTE: Intergrades with <em>Monardella purpurea</em> (in KR, NCoR), <em>Monardella linoides</em>, <em>Monardella eremicola</em>, and possibly <em>Monardella follettii</em>. Type specimen of <em>Monardella odoratissima</em> subsp. <em>odoratissima</em> is from northern Washington; if recognized taxonomically, ashy-gray, pale, chaffy-bracted, puberulent plants of northeastern Siskiyou Co. assignable to subsp. <em>odoratissima</em>. The distribution of this variant is generally from Little Mount Hoffman (Siskiyou Co.) northeastern to Oregon; more study needed. Variation in California generally as follows: conical glands on stems widespread, but lacking in Wrn and northern SN (southwestern Plumas and northern Sierra cos.); leaf hairs most dense in NCoRH (Glenn and Tehama cos.) and central SN (Madera, Tulare, and northeastern El Dorado cos.); serrate leaves occur in the vicinity of Sonora Pass (Mono and Tuolumne cos.) and near Camel Peak (Plumas Co.), possibly reflecting intergradation with <em>Monardella sheltonii</em>. Leaf blade length-to-width ratio generally < 2 in NCoRH, southern CaR, and northern SN at < 2000 m elevation; leaf blade length-to-width ratio > 3.8 in central SN at > 2000 m elevation (leaf blade width generally negatively correlated with elevation); bract hairs generally least dense in central SN (Mono Co.), most dense in northern NCoRH and lower elevations of southern SN (Madera and Tulare cos.). Plants with only scarious bracts common in Wrn and eastern CaR of Siskiyou Co.<br />
<span class="erratum-detail"> 'ashy-gray, pale, chaffy-bracted, puberulent plants of northeastern Siskiyou Co. have been called subsp. <em>odoratissima</em>.' made 'if recognized taxonomically, ashy-gray, pale, chaffy-bracted, puberulent plants of northeastern Siskiyou Co. assignable to subsp. <em>odoratissima</em>.' [as UNABRIDGED NOTE not in TJM2; not abbreviated in eFlora]</span><br />
2015 04 30</p></p><br /><br />
<p><strong>p.</strong></p> 848<br />
MONARDELLA odoratissima<br />
NOTE: Ashy-gray, pale, chaffy-bracted, puberulent pls of ne Siskiyou Co. that have been identified as <em>M. odoratissima</em> subsp. <em>o.</em> intergrade or are intermediate in morphology between subspecies <em>glauca</em> and <em>pallida</em>; if recognized taxonomically, pls in NCoRH with spreading, soft, wavy lf hairs (and highly variable bract morphology) assignable to <em>Monardella odoratissima</em> subsp. <em>pinetorum</em> (Heller) Epling (study needed).<br />
