<p><strong>p.</strong></p> 38<br />
Klamath Ranges Subregion (KR). In the east, the boundary between the predominantly metamorphic KR and the volcanic CaR lies east and north of Shasta Lake, incorporating the McCloud and Hosselkus limestone formations. In the southeast, the boundary generally excludes the chaparral and foothill-pine/blue-oak woodland vegetation of the Inner North Coast Ranges District (NCoRI) in southwestern Shasta and northwestern Tehama counties.<br />
<span class="erratum-detail"> 'In the east, the boundary between the predominantly metamorphic KR and the volcanic CaR is interpreted to be near Interstate 5. In the southeast, the boundary generally excludes the chaparral and pine/oak woodland vegetation of the Inner North Coast Ranges District (NCoRI) in western Shasta and Tehama counties.' made 'In the east, the boundary between the predominantly metamorphic KR and the volcanic CaR lies east and north of Shasta Lake, incorporating the McCloud and Hosselkus limestone formations. In the southeast, the boundary generally excludes the chaparral and foothill-pine/blue-oak woodland vegetation of the Inner North Coast Ranges District (NCoRI) in southwestern Shasta and northwestern Tehama counties.'</span><br />
2016 01 26</p></p><br /><br />
<p><strong>p.</strong></p> 38<br />
CASCADE RANGES REGION (CaR). This region, characterized by volcanics, is bounded to the north by Oregon, to the west by the predominantly metamorphic KR, to the southwest by agricultural land or grassland of the GV, to the southeast by the Sierra Nevada Region (SN), and to the east by the juniper woodland of the GB.<br />
<span class="erratum-detail"> 'This region, characterized by volcanics, is bounded to the north by Oregon, to the west by the pre- dominantly metamorphic KR (generally along Interstate 5) and NCoRI (along the Sacramento River between Redding and Red Bluff), to the southwest by agricultural land or grassland of the GV, to the southeast by the Sierra Nevada Region (SN), and to the east by the juniper woodland of the GB.' made 'This region, characterized by volcanics, is bounded to the north by Oregon, to the west by the predominantly metamorphic KR, to the southwest by agricultural land or grassland of the GV, to the southeast by the Sierra Nevada Region (SN), and to the east by the juniper woodland of the GB.'</span><br />
2016 01 26</p></p><br /><br />
<p><strong>p.</strong></p> 39<br />
Cascade Range Foothills Subregion (CaRF). This subregion, in the southwestern part of CaR, is characterized by chaparral and blue-oak/foothill-pine woodland at about 100&ndash;500 m in elevation. The northern CaRF and northern NCoRI combined with the southern KR form a continuous horseshoe-shaped band of similar foothill vegetation along the northern margin of the GV.<br />
<span class="erratum-detail"> 'This subregion, in the southwestern part of CaR, is characterized by chaparral and blue-oak/foothill-pine woodland at about 100&ndash;500 m in elevation. The CaRF and the adjacent NCoRI and northern Sierra Nevada Foothills District (n SNF) comprise a horseshoe-shaped area of similar foothill vegetation around the northern boundaries of the GV.' made 'This subregion, in the southwestern part of CaR, is characterized by chaparral and blue-oak/foothill-pine woodland at about 100&ndash;500 m in elevation. The northern CaRF and northern NCoRI combined with the southern Kr form a continuous horseshoe-shaped band of similar foothill vegetation along the northern margin of the GV.'</span><br />
2016 01 26</p></p><br /><br />
