UNABRIDGED<br />
WAIF<br />
LATHYRUS aphaca<br />
TAXON AUTHOR: L.<br />
HABIT+: Annual, glabrous.<br />
STEM: angled or flanged but not winged.<br />
LEAF: stipules 1&ndash;5 cm, leaflet-like, lanceolate to ovate, hastate-sagittate at base; leaflets 0; tendril coiled, not branched.<br />
INFLORESCENCE: 1(2)-flowered; peduncle 2&ndash;3 cm.<br />
FLOWER: calyx lobes &plusmn; 2 &times; tube; corolla 10&ndash;14 mm, yellow.<br />
FRUIT: 2&ndash;4 cm, glabrous.<br />
CHROMOSOMES: 2n=14.<br />
ECOLOGY: Uncommon. Disturbed places;<br />
ELEVATION: especially < 500 m.<br />
BIOREGIONAL DISTRIBUTION: n NCo, s NCoRI;<br />
DISTRIBUTION OUTSIDE CALIFORNIA: to WA, e US; native to Eurasia, Africa.<br />
FLOWERING TIME: Apr&ndash;Jun<br />
